(()=>{'use strict';
 let usageCache,usageTime=0,usageBusy=false;async function usage(){const box=document.querySelector('#wallet-provider-status');if(!box||usageBusy)return;usageBusy=true;try{if(!usageCache||Date.now()-usageTime>60000){usageCache=await api('/api/wallet/usage');usageTime=Date.now();}const d=usageCache;box.innerHTML='<p>الإصدارات والتحديثات المستخدمة: <strong>'+esc(String(d.count))+' / '+esc(String(d.limit))+'</strong> · المتبقي '+esc(String(d.remaining))+'</p><p>الخطة: '+esc(d.plan)+' · تتجدد الحصة '+esc(String(d.resetDate))+'</p>'+(d.compatibility?.enabled?'<p>قالب العرض المتوافق مفعّل للبطاقات الجديدة والحالية · تحديثات متبقية: <strong>'+esc(String(d.compatibility.pending))+'</strong>'+(d.compatibility.retrying?' · قيد إعادة المحاولة: '+esc(String(d.compatibility.retrying)):'')+'</p>':'')+(d.trialExpiresAt?'<p class="notice">تنتهي تجربة المزود في '+esc(new Date(d.trialExpiresAt).toLocaleDateString('ar-SA'))+'. استمرار التصاميم المخصصة والتحديثات بعد التجربة يتطلب خطة تدعمها لدى المزود.</p>':'');}catch(e){box.textContent=e.message;}finally{usageBusy=false;}}const previous=render;render=function(){previous();if(window.RIJAA_DEMO||!serverMode||!principal)return;
 if(role==='admin'&&view==='health'&&!db.scopedBusiness){const main=document.querySelector('main');if(main&&!main.querySelector('#wallet-provider-status'))main.insertAdjacentHTML('beforeend','<section class="panel mt"><h2>Apple وGoogle Wallet</h2><div id="wallet-provider-status" aria-live="polite">جارٍ قراءة حصة المزود…</div></section>');usage();}if(principal.kind==='customer'&&clientStage==='card'){const host=document.querySelector('.enroll-issued-panel,.phone');if(host&&!host.querySelector('[data-wallet-issue]'))host.insertAdjacentHTML('beforeend','<div class="mt"><button class="btn primary full" data-wallet-issue>أضف بطاقتي إلى Apple / Google Wallet</button><p class="sub">تصدر البطاقة برصيدك الحالي، ويختلف ترتيبها حسب المحفظة. يرسل للمزود تصميم البطاقة ورمز العضوية والرصيد فقط.</p></div>');}
 if(role==='owner'&&view==='mycards'){const cards=Array.from(document.querySelectorAll('main article')).filter(el=>el.querySelector('[data-action="edit-program"]')||el.querySelector('h2'));const shops=db.shops.filter(s=>!s.archivedAt);cards.forEach((el,i)=>{const sh=shops[i];if(!sh)return;el.insertAdjacentHTML('beforeend','<button class="btn secondary full mt" data-wallet-preview="'+esc(sh.id)+'">تجربة إصدار Wallet لهذا التصميم</button>');});}
 };
 async function issue(button,preview){button.disabled=true;const prior=button.textContent;button.textContent='جارٍ تجهيز بطاقة المحفظة…';try{const id=preview||principal.shop;const result=await api('/api/wallet/issue',{shop:id,...(preview?{preview:true}:{}),...(db.scopedBusiness?{scope:db.scopedBusiness}:{})});const apple='/api/wallet/apple?shop='+encodeURIComponent(id)+(preview?'&preview=1':'')+(db.scopedBusiness?'&scope='+encodeURIComponent(db.scopedBusiness):'');modal(preview?'تجربة تصميم Wallet':'بطاقتك جاهزة للمحفظة','<p>اختر محفظة جهازك. بعد الإضافة تتحدث الزيارات والنقاط والمكافآت تلقائيًا؛ وصول التحديث للجوال يعتمد على المحفظة والاتصال.</p>'+(preview?'<p class="notice">هذه بطاقة اختبار للتصميم فقط؛ رمزها لا يسجل زيارات أو مكافآت فعلية.</p>':'')+'<div class="actions"><a class="btn primary" href="'+esc(apple)+'">إضافة إلى Apple Wallet</a><a class="btn primary" target="_blank" rel="noopener noreferrer" href="'+esc(result.googleSaveUrl)+'">إضافة إلى Google Wallet</a></div><p class="sub">قد تختلف الخلفية وتوزيع العناصر بين Apple وGoogle وإصدارات النظام.</p>');}catch(e){toast(e.message);}finally{button.disabled=false;button.textContent=prior;}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-wallet-issue],[data-wallet-preview]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();issue(b,b.dataset.walletPreview||'');},true);
})();
